            // if call did not revert, betLimit must remain unchanged because caller is not owner
            assertEq(c.currentBetLimit(), expectedLimit);
        } catch {
            // if call reverted, betLimit must remain unchanged
            assertEq(c.currentBetLimit(), expectedLimit);
        }
    }
}

