contract InvMutTest {
    C c;
    bool didRevert;

    constructor(C _c) {
        c = _c;
    }

    function test(address nonOwner) public {
        require(nonOwner != address(0));
        didRevert = false;
        assembly {
            mstore(0, nonOwner)
            pop(call(gas(), sload(c.slot), 0, 0, 0, 0, 0))
            // We check that calling OpenToThePublic from nonOwner reverts on P
        }
        // To observe the revert, we actually need to make a proper call:
        // Since onlyOwner uses msg.sender, we need a different approach:
        // We can use transferAnyERC20Token as an onlyOwner function that returns a value.
        // On P, call from nonOwner reverts. On M, it returns a value.
        // We capture revert by checking success of a staticcall pattern:
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferAnyERC20Token(address,address,uint256)", address(0), address(0), 0));
        // Actually we need to set msg.sender to nonOwner. We do this by calling from this contract,
        // but we can't change msg.sender of this contract. So we can use a delegatecall or low-level call?
        // Standard pattern: use a low-level call from a different address is not possible without cheatcodes.
        // Hence we rely on a different onlyOwner function that is pure/view? Only OpenToThePublic is state-changing.
        // We can check revert by calling OpenToThePublic from a different context: we send a call from this contract,
        // but msg.sender will be this contract's address, which is not owner. So calling c.OpenToThePublic() here will revert on P.
        // That's the simplest way.
        didRevert = !success;
        // But wait, transferAnyERC20Token requires a token address. If we pass address(0), it may revert for other reasons.
        // Better: use a public view function that has onlyOwner? None exist. We must use a state-changing call.
        // Let's just call OpenToThePublic from this contract, which is not the owner.
        // We'll store the revert result.
        (bool success2, ) = address(c).call(abi.encodeWithSignature("OpenToThePublic()"));
        // On P: call from non-owner reverts -> success2 == false. On M: succeeds -> true.
        assert(success2 == false);
    }
}

